from copy import deepcopy
from typing import Any, Dict, List, Optional, Union

def blank(v: Any) -> bool:
    return v is None or (isinstance(v, str) and v.strip() == '')

def text(v: Any) -> str:
    if v is None:
        return ''
    if isinstance(v, float) and v.is_integer():
        return str(int(v))
    return str(v)

def normalize(v: Any, steps: List[str]) -> str:
    s = text(v)
    for step in steps:
        if step == 'strip':
            s = s.strip()
        elif step == 'upper':
            s = s.upper()
        elif step == 'lower':
            s = s.lower()
        elif step == 'collapse_spaces':
            s = ' '.join(s.split())
        elif step == 'digits_only':
            s = ''.join(ch for ch in s if ch.isdigit())
    return s

def evaluate_condition(row: Dict[str, Any], cond: Dict[str, Any]) -> bool:
    col = cond["column"]
    op = cond["op"]
    val = row.get(col)
    value = cond.get("value")

    if op == 'blank':
        return blank(val)
    if op == 'not_blank':
        return not blank(val)

    # For other ops we need a comparison value
    if op == 'in':
        # value is a list
        for item in value:
            if evaluate_condition(row, {"column": col, "op": "eq", "value": item}):
                return True
        return False

    # Helper to get comparable forms
    def to_num(x):
        if isinstance(x, (int, float)):
            return x
        return None

    val_num = to_num(val)
    value_num = to_num(value)

    if op in ('eq', 'ne', 'gt', 'gte', 'lt', 'lte'):
        # Numeric comparison if both are numbers
        if val_num is not None and value_num is not None:
            if op == 'eq':
                res = val_num == value_num
            elif op == 'ne':
                res = val_num != value_num
            elif op == 'gt':
                res = val_num > value_num
            elif op == 'gte':
                res = val_num >= value_num
            elif op == 'lt':
                res = val_num < value_num
            elif op == 'lte':
                res = val_num <= value_num
            return res
        # String comparison if both are strings and val not blank
        if isinstance(val, str) and isinstance(value, str) and not blank(val):
            sv = val.strip()
            vv = value.strip()
            if op == 'eq':
                return sv.casefold() == vv.casefold()
            if op == 'ne':
                return sv.casefold() != vv.casefold()
            if op == 'gt':
                return sv > vv
            if op == 'gte':
                return sv >= vv
            if op == 'lt':
                return sv < vv
            if op == 'lte':
                return sv <= vv
        return False

    if op == 'contains':
        if isinstance(val, str) and isinstance(value, str):
            return text(value).strip().casefold() in text(val).casefold()
        return False

    if op == 'starts_with':
        if isinstance(val, str) and isinstance(value, str):
            return text(val).strip().casefold().startswith(text(value).strip().casefold())
        return False

    return False

def run(rows: List[Dict[str, Any]], reference: Dict[str, List[Dict[str, Any]]]) -> Dict[str, Any]:
    # Validate input columns
    required_input_cols = ["Lead ID", "Full Name", "Email", "Company", "Phone"]
    for i, row in enumerate(rows):
        for col in required_input_cols:
            if col not in row:
                raise ValueError(f"Missing column: {col}")

    # Validate reference
    if "crm" not in reference:
        raise ValueError("Missing reference: crm")
    crm_rows = reference["crm"]
    for i, r in enumerate(crm_rows):
        for field in ["Email", "Owner"]:
            if field not in r:
                raise ValueError(f"Missing field in crm: {field}")

    # Work on a deep copy
    rows = deepcopy(rows)

    # Step 1: clean_text
    for row in rows:
        for col in ["Full Name", "Email"]:
            val = row.get(col)
            if isinstance(val, str):
                s = val.strip()
                s = ' '.join(s.split())  # collapse_spaces
                # case none -> unchanged
                row[col] = s if s != '' else None

    # Step 2: split
    for row in rows:
        val = row.get("Full Name")
        if blank(val):
            row["First Name"] = None
            row["Last Name"] = None
        else:
            s = text(val).strip()
            parts = s.split(None, 1)  # separator is exactly ' '
            first = parts[0].strip() if parts else ''
            last = parts[1].strip() if len(parts) > 1 else ''
            row["First Name"] = first if first != '' else None
            row["Last Name"] = last if last != '' else None

    # Step 3: lookup
    # Build index
    index: Dict[str, List[Dict[str, Any]]] = {}
    for ref_row in crm_rows:
        key = ref_row["Email"]
        norm_key = normalize(key, ["strip", "lower"])
        if norm_key != '':
            index.setdefault(norm_key, []).append(ref_row)

    for row in rows:
        # Ensure Owner column exists
        if "Owner" not in row:
            row["Owner"] = None
        email = row.get("Email")
        norm_email = normalize(email, ["strip", "lower"])
        if norm_email != '' and norm_email in index:
            matches = index[norm_email]
            if len(matches) == 1:
                match = matches[0]
                # mode fill_blanks
                if blank(row["Owner"]):
                    row["Owner"] = match["Owner"]
                status = "matched"
            else:
                status = "check manually"
        else:
            status = "Create contact"
        row["CRM Status"] = status

    # Step 4: flag
    for row in rows:
        if "Action" not in row:
            row["Action"] = None
        cond = {"column": "CRM Status", "op": "eq", "value": "Create contact"}
        if evaluate_condition(row, cond):
            row["Action"] = "Create contact"
        else:
            row["Action"] = "Exists in CRM"

    # Prepare output rows with exact column order
    output_cols = ["Lead ID", "Full Name", "First Name", "Last Name", "Email", "Company", "Phone", "Owner", "CRM Status", "Action"]
    output_rows = []
    for row in rows:
        out_row = {col: row.get(col) for col in output_cols}
        output_rows.append(out_row)

    return {"rows": output_rows, "sheets": {}}
